import { AsyncPipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'app-profile',
  imports: [AsyncPipe],
  template: `
    <h1>{{ (user$ | async)?.name }}</h1>
    <img [src]="(user$ | async)?.avatarUrl" alt="" />
    <p>{{ (user$ | async)?.email }}</p>
  `,
})
export class Profile {
  private readonly http = inject(HttpClient);
  // A blueprint: each async pipe subscribes and sends its own GET
  readonly user$ = this.http.get<User>('/api/me');
}

import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-profile',
  template: `
    @if (user(); as u) {
      <h1>{{ u.name }}</h1>
      <img [src]="u.avatarUrl" alt="" />
      <p>{{ u.email }}</p>
    }
  `,
})
export class Profile {
  private readonly http = inject(HttpClient);
  // One subscription, one GET; the template reads the signal
  readonly user = toSignal(this.http.get<User>('/api/me'));
}
